"""Baseline stock operations."""

from .models import InventoryItem


class Inventory:
    def __init__(self) -> None:
        self._items: dict[str, InventoryItem] = {}

    def add_stock(self, sku: str, quantity: int) -> int:
        if quantity <= 0:
            raise ValueError("quantity must be positive")
        item = self._items.setdefault(sku, InventoryItem(sku=sku))
        item.total_stock += quantity
        return item.total_stock

    def remove_stock(self, sku: str, quantity: int) -> int:
        if quantity <= 0:
            raise ValueError("quantity must be positive")
        item = self._items.setdefault(sku, InventoryItem(sku=sku))
        if quantity > item.total_stock:
            raise ValueError("insufficient stock")
        item.total_stock -= quantity
        return item.total_stock

    def available_stock(self, sku: str) -> int:
        return self._items.get(sku, InventoryItem(sku=sku)).total_stock

    def reserve_stock(self, sku: str, quantity: int) -> int:
        if quantity <= 0:
            raise ValueError("quantity must be positive")
        item = self._items.setdefault(sku, InventoryItem(sku=sku))
        available = item.total_stock - item.reserved_stock
        if quantity > available:
            raise ValueError("insufficient available stock")
        item.reserved_stock += quantity
        return item.reserved_stock

    def release_stock(self, sku: str, quantity: int) -> int:
        if quantity <= 0:
            raise ValueError("quantity must be positive")
        item = self._items.setdefault(sku, InventoryItem(sku=sku))
        if quantity > item.reserved_stock:
            raise ValueError("insufficient reserved stock")
        item.reserved_stock -= quantity
        return item.reserved_stock
